/// `openssl rsa -noout -modulus`.
const RSA_N: &str = "";
/// The SEC 1 uncompressed public point (`openssl ec -pubout`).
const EC_PUB: &str = "046156c14d07572dc08c45d77e9105402dfb39aadfa153c8c65e4fe155fd365ca4f3fdee662d689a84e695de4ddb36feec0137c6240725105b5642ba0777b00638";
