const ED_PUB: &str = "8338be0dc3421ae745249cb0883e64ad12785817ce188ddcf04172c4fca4f247";
/// `openssl ec -outform DER` (SEC 1 with [0] prime256v1 and [1] public).
const EC_SEC1_DER: &str = "30770201010420eb2bd0c5877873f3f43afa1ad9c8ff1cdf8cd1e98eaa38beed738afc77fa524ba00a06082a8648ce3d030107a144034200046156c14d07572dc08c45d77e9105402dfb39aadfa153c8c65e4fe155fd365ca4f3fdee662d689a84e695de4ddb36feec0137c6240725105b5642ba0777b00638";
/// `openssl pkcs8 -topk8 -nocrypt -outform DER`.
const EC_PKCS8_DER: &str = "308187020100301306072a8648ce3d020106082a8648ce3d030107046d306b0201010420eb2bd0c5877873f3f43afa1ad9c8ff1cdf8cd1e98eaa38beed738afc77fa524ba144034200046156c14d07572dc08c45d77e9105402dfb39aadfa153c8c65e4fe155fd365ca4f3fdee662d689a84e695de4ddb36feec0137c6240725105b5642ba0777b00638";
/// `openssl pkey -outform DER` (PKCS#8 v1).
const ED_PKCS8_DER: &str = "302e020100300506032b6570042204203a876ceb0adb506670e8d422fb48abddf2007c3e74aa6bffe29eeb799f09300c";

fn hex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

/// The one block with `label`, decoded.
fn pem_der(text: &str, label: &str) -> Vec<u8> {
    let (mut blocks, bad) = pem_blocks(text, label);
    assert_eq!((blocks.len(), bad), (1, 0), "{label}");
    blocks.remove(0)
}

fn refused(b: &[u8]) -> KeyError {
    match parse(b) {
        Ok(k) => panic!("accepted as {}", k.kind()),
        Err(e) => e,
    }
}

fn rsa_n(k: &Key) -> Vec<u8> {
    let Key::Rsa(k) = k else { panic!("not RSA: {}", k.kind()) };
    let mut n = vec![0u8; k.public_key().size()];
    let len = k.public_key().n_be(&mut n);
    n.truncate(len);
    n
}

fn ec_pub(k: &Key) -> Vec<u8> {
    let Key::P256(k) = k else { panic!("not P-256: {}", k.kind()) };
    k.public_key().to_sec1_uncompressed().to_vec()
}

fn ed_pub(k: &Key) -> Vec<u8> {
    let Key::Ed25519(k) = k else { panic!("not Ed25519: {}", k.kind()) };
    k.public_key().to_vec()
}

#[test]
fn rsa_pkcs8_and_pkcs1_pem_and_der() {
    let n = hex(RSA_N);
    assert_eq!(n.len(), 256);
    for (text, label) in [(RSA_PKCS8, "PRIVATE KEY"), (RSA_PKCS1, "RSA PRIVATE KEY")] {
        assert_eq!(rsa_n(&parse(text.as_bytes()).unwrap()), n, "{label} PEM");
        assert_eq!(rsa_n(&parse(&pem_der(text, label)).unwrap()), n, "{label} DER");
    }
}

#[test]
fn p256_sec1_and_pkcs8_pem_and_der() {
    let public = hex(EC_PUB);
    assert_eq!(public.len(), 65);
    for (what, b) in [
        ("SEC 1 PEM (beside EC PARAMETERS)", EC_SEC1.as_bytes().to_vec()),
        ("PKCS#8 PEM", EC_PKCS8.as_bytes().to_vec()),
        ("SEC 1 DER", hex(EC_SEC1_DER)),
        ("PKCS#8 DER", hex(EC_PKCS8_DER)),
    ] {
        assert_eq!(ec_pub(&parse(&b).unwrap()), public, "{what}");
    }
    assert_eq!(pem_der(EC_SEC1, "EC PRIVATE KEY"), hex(EC_SEC1_DER));
    assert_eq!(pem_der(EC_PKCS8, "PRIVATE KEY"), hex(EC_PKCS8_DER));
}

#[test]
fn ed25519_pkcs8_pem_and_der() {
    let public = hex(ED_PUB);
    assert_eq!(ed_pub(&parse(ED_PKCS8.as_bytes()).unwrap()), public);
    assert_eq!(ed_pub(&parse(&hex(ED_PKCS8_DER)).unwrap()), public);
    assert_eq!(pem_der(ED_PKCS8, "PRIVATE KEY"), hex(ED_PKCS8_DER));
}

/// A OneAsymmetricKey v2 (RFC 5958) carrying `public` in `[1]`, around the openssl Ed25519 key.
fn ed_v2(public: &[u8]) -> Vec<u8> {
    let der = hex(ED_PKCS8_DER);
    let p = key::pkcs8(&der).unwrap();
    assert_eq!((p.version, p.alg, p.params), (0, oid::ED25519, AlgParams::Absent));
    let mut bits = vec![0u8];
    bits.extend_from_slice(public);
    build::seq(&[&build::int(&[1]), &build::seq(&[&build::oid(oid::ED25519)]), &build::octets(p.key), &encode_tlv(0x81, &bits)])
}

#[test]
fn ed25519_v2_public_key_checked() {
    let public = hex(ED_PUB);
    assert_eq!(ed_pub(&parse(&ed_v2(&public)).unwrap()), public);
    let mut wrong = public.clone();
    wrong[0] ^= 1;
    assert_eq!(refused(&ed_v2(&wrong)), KeyError::Refused("public key mismatch"));
}

#[test]
fn refusals_by_name() {
    assert_eq!(refused(ENC_PKCS8.as_bytes()), KeyError::Refused("encrypted PKCS#8"));
    assert_eq!(refused(&pem_der(ENC_PKCS8, "ENCRYPTED PRIVATE KEY")), KeyError::Refused("encrypted PKCS#8"));
    assert_eq!(refused(RSA_ENC_PEM.as_bytes()), KeyError::Refused("encrypted PEM"));
    assert_eq!(refused(P384_SEC1.as_bytes()), KeyError::Refused("P-384"));
    assert_eq!(refused(P384_PKCS8.as_bytes()), KeyError::Refused("P-384"));
    assert_eq!(refused(&pem_der(P384_PKCS8, "PRIVATE KEY")), KeyError::Refused("P-384"));
    let two = format!("{ED_PKCS8}{EC_PKCS8}");
    assert_eq!(refused(two.as_bytes()), KeyError::Refused("key count"));
    assert_eq!(refused(b"-----BEGIN CERTIFICATE-----\n-----END CERTIFICATE-----\n"), KeyError::Refused("no private key"));
    // An RSA key whose d is off by one: every component well-formed DER, the key not one key.
    let der = pem_der(RSA_PKCS1, "RSA PRIVATE KEY");
    let parts = key::rsa_private(&der).unwrap();
    let mut d = parts[2].to_vec();
    *d.last_mut().unwrap() ^= 2;
    let mut bad: Vec<&[u8]> = parts.to_vec();
    bad[2] = &d;
    assert_eq!(refused(&key::rsa_private_build(&bad)), KeyError::Refused("RSA components"));
    // The DER as openssl wrote it rebuilds byte for byte through the writer.
    assert_eq!(key::rsa_private_build(&parts), der);
}

#[test]
fn containers_round_trip_and_stay_strict() {
    let spki = key::spki_build(oid::ED25519, &AlgParams::Absent, &[7u8; 32]);
    assert_eq!(&spki[..12], &[0x30, 0x2a, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x70, 0x03, 0x21, 0x00]);
    assert_eq!(key::spki(&spki).unwrap(), (oid::ED25519, AlgParams::Absent, &[7u8; 32][..]));
    let p8 = key::pkcs8_build(oid::EC_PUBLIC_KEY, &AlgParams::Oid(oid::PRIME256V1), b"inner");
    let p = key::pkcs8(&p8).unwrap();
    assert_eq!((p.version, p.alg, p.params, p.key, p.public), (0, oid::EC_PUBLIC_KEY, AlgParams::Oid(oid::PRIME256V1), &b"inner"[..], None));
    let ec = hex(EC_SEC1_DER);
    let e = key::ec_private(&ec).unwrap();
    assert_eq!((e.curve, e.public.map(<[u8]>::to_vec)), (Some(oid::PRIME256V1), Some(hex(EC_PUB))));
    assert!(Der::new(&[0x02, 0x81, 0x01, 0x00]).uint().is_err(), "non-minimal length");
    assert!(Der::new(&[0x02, 0x02, 0x00, 0x01]).uint().is_err(), "non-minimal integer");
    let mut trailing = p8.clone();
    trailing.push(0);
    assert!(key::pkcs8(&trailing).is_err(), "trailing data");
}
